use verus::prelude::*;

#[requires(n >= 0)]             // n must be non-negative
#[requires(k >= 0 && k <= n)]   // 0 ≤ k ≤ n
#[ensures(result.len() == 2)]   // always returns exactly two elements
#[ensures(
    if k == 0 || k == n {
        // in the zero‐ or all‐selected case, we return [0,0]
        result[0] == 0 && result[1] == 0
    } else {
        // otherwise we return [1, min(n−k, 2*k)]
        let unselected: i8 = n - k;
        let two_k: i8 = 2 * k;
        // the code does an i16‐min then casts back to i8; this is equivalent to
        // taking the min in i8 since both operands fit
        let max_good: i8 = if unselected < two_k { unselected } else { two_k };
        result[0] == 1 && result[1] == max_good
    }
)]
fn solve(n: i8, k: i8) -> Vec<i8> {
    // If no items are selected or all items are selected,
    // there are zero "good" unselected items.
    if k == 0 || k == n {
        return vec![0, 0];
    }

    // Number of unselected items
    let unselected = n - k;

    // Compute 2 * k in a larger integer to avoid overflow,
    // then take the minimum with `unselected`.
    let two_k = (k as i16) * 2;
    let max_good = (unselected as i16).min(two_k) as i8;

    // At least one good unselected item in this branch.
    vec![1, max_good]
}

